/bin/bash -lc "python - <<'PY'
mods=['numpy','scipy','statsmodels','sklearn']
for m in mods:
 try:
  x=__import__(m); print(m,getattr(x,'__version__','installed'))
 except Exception as e: print(m,'unavailable',type(e).__name__)
PY
R --version | head -n 1 || true"

